```java
import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        long coeff;
        int f;

        Node(long coeff, int f) {
            this.coeff = coeff;
            this.f = f;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        long[] T = new long[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            T[i] = Long.parseLong(st.nextToken());
        }
        Arrays.sort(T);

        int[] F = new int[M];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < M; i++) {
            F[i] = Integer.parseInt(st.nextToken());
        }

        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> {
            if (a.coeff != b.coeff) return Long.compare(a.coeff, b.coeff);
            return Integer.compare(a.f, b.f);
        });

        for (int f : F) {
            pq.add(new Node(0, f));
        }

        long ans = 0;
        for (int i = 0; i < N; i++) {
            Node cur = pq.poll();
            long coeff = cur.coeff;
            ans += coeff * T[N - 1 - i];
            pq.add(new Node(coeff + cur.f, cur.f));
        }

        System.out.println(ans);
    }
}
```

